settings.custom_css:
selector {
    background: rgba(255, 255, 255, 0.2); /* fundo semi-transparente */
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px); /* suporte pra Safari */
}

selector {
    width: 1000px !important;
    white-space: nowrap !important; /* impede quebra de linha */
    overflow: visible !important;   /* garante que não corte o conteúdo */
}

selector{
    position: absolute;
}


.scroll-left,
.scroll-right,
.scroll-bottom,
.scroll-top {
    opacity: 0;
    filter: blur(10px); /* aqui o blur inicial */
    transition: 0.6s all ease;
}

/* Mantém seus transforms separados */
.scroll-left {
    transform: translate3d(-30px, 0, 0);
}

.scroll-right {
    transform: translate3d(30px, 0, 0);
}

.scroll-bottom {
    transform: translate3d(0, 80px, 0);
}

.scroll-top {
    transform: translate3d(0, -80px, 0);
}

/* Estado ativo */
.ativo {
    opacity: 1;
    filter: blur(0); /* remove o blur */
    transform: translate3d(0, 0, 0);
}

page_settings.custom_css:
.destaque1 { font-family: 'Playfair Display', serif; font-style: italic; font-weight: 400; line-height: 1.1em;font-size: 158%; }

.destaque2 { font-family: 'Playfair Display', serif; font-style: italic; font-weight: 400; line-height: 1.1em; }

::selection {
    background-color: rgba(255, 255, 255, 0.125);
}

html, body {
    overflow-x: hidden;
}

p:last-of-type {
    margin-bottom: 0;
}

body::-webkit-scrollbar {
    width: 10px; /* largura da barra de rolagem */
}

body::-webkit-scrollbar-track {
    background-color: #111111; /* cor da área de rastreamento */
}

body::-webkit-scrollbar-thumb {
    background: linear-gradient(90deg, #fff, #fff); /* cor do SCROLL*/
    border-radius: 15px; /* arredondamento do SCROLL */
    border: 2px solid #111111; /* cria espaçamento em torno do SCROLL*/
}


[data-elementor-type="wp-page"]{
    overflow: hidden;
}

[data-elementor-type="wp-post"]{
    overflow: hidden;
}
